    input  logic x,
    input  logic y,
    output logic z
);

    // Internal state register
    logic [1:0] state;

    // State encoding
    // 2'b00: idle / z=1
    // 2'b01: z=0
    // 2'b10: z=1 (after specific pattern)
    // 2'b11: z=1 (initial/hold)

    always_ff @(posedge x or posedge y) begin
        // Synchronous reset via y
        if (y) begin
            state <= 2'b00;
            z     <= 1'b1;
