module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Byte shift register: holds the last 3 valid bytes
    // byte_reg[2] = most recent, byte_reg[1] = middle, byte_reg[0] = oldest
    logic [7:0] byte_reg [2:0];

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            IDLE: begin
                if (in[3]) begin
                    next_state = BYTE1;
                end else begin
                    next_state = IDLE;
                end
            end
            BYTE1: begin
                next_state = BYTE2;
            end
            BYTE2: begin
                next_state = BYTE3;
            end
            BYTE3: begin
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // Datapath / state flip-flops (sequential, positive edge)
    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            byte_reg[0] <= 8'h00;
            byte_reg[1] <= 8'h00;
            byte_reg[2] <= 8'h00;
            done       <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    if (in[3]) begin
                        byte_reg[2] <= in;
                        done       <= 1'b0;
                    end else begin
                        // keep current bytes
                        done <= 1'b0;
                    end
                end
                BYTE1: begin
                    // Shift in second byte; first byte stays in byte_reg[2]
                    byte_reg[1] <= in;
                    done       <= 1'b0;
                end
                BYTE2: begin
                    // Shift in third byte
                    byte_reg[0] <= in;
                    done       <= 1'b0;
                end
                BYTE3: begin
                    // Third byte received – assert done in this cycle
                    // out_bytes valid when done is asserted
                    out_bytes <= {byte_reg[2], byte_reg[1], byte_reg[0]};
                    done       <= 1'b1;
                    // After this cycle we go IDLE next clock
                end
            endcase
        end
    end

    // Asynchronous reset cleanup: ensure done is low when reset asserted
    // (covered by the reset block above, but added for clarity)
    always_ff @(posedge clk) begin
        if (reset) done <= 1'b0;
    end

endmodule

