module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: BCD digits
);

    // Internal registers for the 4 BCD digits (ones, tens, hundreds, thousands)
    logic [3:0] ones;
    logic [3:0] tens;
    logic [3:0] hundreds;
    logic [3:0] thousands;

    // ena outputs: enable signal for the next higher digit
    // ena[0] -> tens, ena[1] -> hundreds, ena[2] -> thousands
    assign ena = {tens[3], hundreds[3], thousands[3]}; // MSB of each digit indicates carry

    // BCD counter logic
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            ones     <= 4'b0;
            tens     <= 4'b0;
            hundreds <= 4'b0;
            thousands <= 4'b0;
        end else begin
            // Increment ones digit every clock cycle
            ones <= ones + 4'b1;

            // If ones rolls over from 9 to 0 (i.e., ones == 4'd9 and we add 1),
            // propagate carry to tens.
            // BCD correction: when ones reaches 10 (0b1010), it should reset to 0 and carry.
            // Since we always add 1, we check if the new value is 10 or more (but binary count goes 0..15).
            // Standard BCD counter: increment next digit when current digit == 9 and we add 1.
            if (ones == 4'd9) begin
                ones <= 4'b0;
                // Check tens carry
                if (tens == 4'd9) begin
                    tens <= 4'b0;
                    if (hundreds == 4'd9) begin
                        hundreds <= 4'b0;
                        if (thousands == 4'd9) begin
                            thousands <= 4'b0;
                        end else begin
                            thousands <= thousands + 4'b1;
                        end
                    end else begin
                        hundreds <= hundreds + 4'b1;
                    end
                end else begin
                    tens <= tens + 4'b1;
                end
            end
            // If ones is not 9, no carry propagation needed.
        end
    end

    // Concatenate the 4 digits to form the 16-bit output q
    assign q = {thousands, hundreds, tens, ones};

