module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // FSM state encoding (2 bits)
    typedef enum logic [1:0] {
        STATE_A   = 2'b00,
        STATE_B   = 2'b01,
        STATE_C   = 2'b10,
        STATE_D   = 2'b11
    } state_t;

    // State register (synchronous, active-low reset)
    state_t state, next_state;

    // Outputs (logic for combinational assignment to outputs)
    logic f_reg, g_reg;

    // Output assignments (glitch-free via registered outputs)
    assign f = f_reg;
    assign g = g_reg;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            STATE_A: begin
                // As long as reset is asserted, stay in A.
                // When reset is de-asserted, go to B after next clock edge.
                if (!resetn) begin
                    next_state = STATE_A;
                end else begin
                    next_state = STATE_B;
                end
            end

            STATE_B: begin
                // After reset de-assertion, set f to 1 for one clock cycle,
                // then move to C.
                next_state = STATE_C;
            end

            STATE_C: begin
                // Monitor x for the sequence 1, 0, 1 over three successive cycles.
                // If the sequence is detected, go to D; otherwise stay in C.
                if (x_shift == 2'b101) begin
                    next_state = STATE_D;
                end else begin
                    next_state = STATE_C;
                end
            end

            STATE_D: begin
                // g has been set to 1. Now monitor y.
                // If y becomes 1 within two clock cycles, keep g = 1 (stay in D).
                // If y does not become 1 within two cycles, set g = 0 (go to E).
                if (y_cnt == 2'b11) begin
                    next_state = STATE_E;
                end else begin
                    next_state = STATE_D;
                end
            end

            default: next_state = STATE_A;
        endcase
    end

    // Sequence and counter logic (registered)
    // We use additional registers to track the x-sequence and y-timeout.
    logic [1:0] x_shift; // shifts in x values: bit0 = latest, bit1 = previous
    logic [1:0] y_cnt;   // counts cycles since y last toggled (0,1,2+)

    // Update shift register and counter on positive edge of clock
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state       <= STATE_A;
            f_reg       <= 1'b0;
            g_reg       <= 1'b0;
            x_shift     <= 2'b00;
            y_cnt       <= 2'b00;
        end else begin
            // State transition
            state <= next_state;

            // Output f: set to 1 for one clock cycle in STATE_B
            if (state == STATE_B) begin
                f_reg <= 1'b1;
            end else begin
                f_reg <= 1'b0;
            end

            // Output g: set to 1 when entering STATE_D, cleared in STATE_E
            if (next_state == STATE_D) begin
                g_reg <= 1'b1;
            end else if (state == STATE_E) begin
                g_reg <= 1'b0;
            end

            // Update x_shift: shift in current x
            x_shift <= {x, x_shift[1:1]};

            // Update y_cnt: increment if y is 0, reset if y is 1
            if (y) begin
                y_cnt <= 2'b00;
            end else begin
                if (y_cnt < 2'b11) begin
                    y_cnt <= y_cnt + 1'b1;
                end
            end

            // Next-state refinements based on sequence detection
            // (This block replaces the placeholder logic in the comb block)
            case (state)
                STATE_C: begin
                    // Detect sequence x=1,0,1 using the shift register.
                    // The sequence is detected when we see 1 (new), 0 (prev), 1 (two prev).
                    if (x_shift == 2'b101) begin
                        next_state = STATE_D;
                    end else begin
                        next_state = STATE_C;
                    end
                end

                STATE_D: begin
                    // If y=1 within two cycles, stay in D; else go to E.
                    // y_cnt counts cycles with y=0. If it reaches 2, timeout.
                    if (y_cnt == 2'b11) begin
                        // Two cycles with y=0 have passed without y=1.
                        next_state = STATE_E;
                    end else begin
                        next_state = STATE_D;
                    end
                end

                default: next_state = STATE_A;
            endcase
        end
    end

endmodule

