module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        WALK_LEFT,    // 000: Walking left on ground
        WALK_RIGHT,   // 001: Walking right on ground
        FALLING,      // 010: Falling (aaah)
        DIGGING,      // 011: Digging on ground
        SPLATTERED    // 100: Splattered (all outputs 0)
    } state_t;

    // Signals
    state_t state, next_state;
    logic [4:0] fall_counter;  // Counter for fall duration (max 20+)

    // Output assignments (Moore machine - outputs depend only on state)
    assign walk_left  = (state == WALK_LEFT);
    assign walk_right = (state == WALK_RIGHT);
    assign aaah       = (state == FALLING);
    assign digging    = (state == DIGGING);

    // State register (positive edge triggered, async reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            state <= WALK_LEFT;
        else
            state <= next_state;
    end

    // Next state logic (combinational)
    always_comb begin
        // Default: stay in current state
        next_state = state;

        // Priority: fall > dig > switch directions
        // 1. SPLATTERED state: stay splattered forever
        if (state == SPLATTERED) begin
            next_state = SPLATTERED;
        end
        // 2. FALLING state
        else if (state == FALLING) begin
            // If ground reappears after falling > 20 cycles -> splatter
            if (ground && (fall_counter >= 5'd20))
                next_state = SPLATTERED;
            // If ground disappears while still falling -> stay falling
            else if (!ground)
                next_state = FALLING;
            // If ground reappears and fall_counter < 20 -> resume walking in same direction
            else
                next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
        end
        // 3. DIGGING state
        else if (state == DIGGING) begin
            // If ground disappears while digging -> start falling
            if (!ground)
                next_state = FALLING;
            // If ground=1 and dig=0 -> resume walking in current direction
            else if (ground && !dig)
                next_state = (state == WALK_LEFT) ? WALK_LEFT : WALK_RIGHT;
        end
        // 4. WALK_LEFT state
        else if (state == WALK_LEFT) begin
            // Bumped on left -> walk right
            if (bump_left && !bump_right)
                next_state = WALK_RIGHT;
            // Bumped on right -> walk left (stay walking left)
            else if (bump_right)
                next_state = WALK_LEFT;
            // Bumped on both sides -> switch directions (walk right)
            else if (bump_left && bump_right)
                next_state = WALK_RIGHT;
            // If ground disappears -> start falling
            else if (!ground)
                next_state = FALLING;
            // If told to dig while on ground -> start digging
            else if (ground && dig)
                next_state = DIGGING;
        end
        // 5. WALK_RIGHT state
        else if (state == WALK_RIGHT) begin
            // Bumped on right -> walk left
            if (bump_right && !bump_left)
                next_state = WALK_LEFT;
            // Bumped on left -> walk right (stay walking right)
            else if (bump_left)
                next_state = WALK_RIGHT;
            // Bumped on both sides -> switch directions (walk left)
            else if (bump_left && bump_right)
                next_state = WALK_LEFT;
            // If ground disappears -> start falling
            else if (!ground)
                next_state = FALLING;
            // If told to dig while on ground -> start digging
            else if (ground && dig)
                next_state = DIGGING;
        end
    end

    // Fall counter logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            fall_counter <= 5'd0;
        end else begin
            case (state)
                FALLING: begin
                    // Count cycles while falling
                    if (fall_counter < 5'd31) // Max value safety
                        fall_counter <= fall_counter + 1'd1;
                    else
                        fall_counter <= 5'd31;
                end
                default: begin // WALK_LEFT, WALK_RIGHT, DIGGING, SPLATTERED
                    fall_counter <= 5'd0;
                end
            endcase
        end
    end

endmodule

