module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    logic [1:0] prev_level;
    logic [1:0] curr_level;
    logic [2:0] sensor_mask;

    // Decode current sensor mask and level
    always_comb begin
        if (s[2]) begin
            sensor_mask = 3'b111;
            curr_level    = 2'b11; // Above highest
        end else if (s[1]) begin
            sensor_mask = 3'b011;
            curr_level    = 2'b10; // Between s[2] and s[1]
        end else if (s[0]) begin
            sensor_mask = 3'b001;
            curr_level    = 2'b01; // Between s[1] and s[0]
        end else begin
            sensor_mask = 3'b000;
            curr_level    = 2'b00; // Below lowest
        end
    end

    // Level change detection
    always_ff @(posedge clk) begin
        if (reset) begin
            prev_level <= 2'b00;
        end else begin
            prev_level <= curr_level;
        end
    end

    // Output assignment logic
    always_comb begin
        // Default assignments (all outputs high = off/maximum flow)
        fr2 = 1'b1;
        fr1 = 1'b1;
        fr0 = 1'b1;
        dfr = 1'b1;

        // Synchronous reset condition: equivalent to long low level
        if (!reset && (sensor_mask == 3'b000)) begin
            fr2 = 1'b0;
            fr1 = 1'b0;
            fr0 = 1'b0;
            dfr = 1'b0;
        end else begin
            // Level-based nominal flow
            case (curr_level)
                2'b11: begin // Above s[2]
                    // None
                end
                2'b10: begin // Between s[2] and s[1]
                    fr0 = 1'b0;
                end
                2'b01: begin // Between s[1] and s[0]
                    fr0 = 1'b0;
                    fr1 = 1'b0;
                end
                2'b00: begin // Below s[0]
                    fr0 = 1'b0;
                    fr1 = 1'b0;
                    fr2 = 1'b0;
                end
            endcase

            // Supplemental flow: increase if previous level was lower than current
            if (prev_level < curr_level) begin
                dfr = 1'b0;
            end
        end
    end

endmodule
